record.field:
{"type":"object","properties":{
            "title":{"type":"string","description":"Title of the deviation"},
            "description":{"type":"string","description":"Detailed description of the deviation and its impact"},
            "minion":{"type":"string","description":"Affected machine/minion","default":""},
            "service":{"type":"string","description":"Affected service","default":""},
            "severity":{"type":"string","description":"major, minor, critical","default":"minor"}
        },"required":["title","description"]}

async def execute(title, description, minion="", service="", severity="minor"):
    """Create a nonconformity in the management system."""
    Nonconformity = env.get("mgmtsystem.nonconformity")
    if not Nonconformity:
        return "ERROR: mgmtsystem.nonconformity model not available"

    nc_description = description
    context = []
    if minion:
        context.append(f"Affected machine: {minion}")
    if service:
        context.append(f"Affected service: {service}")
    if context:
        nc_description += "\n\n--- Infrastructure Context ---\n" + "\n".join(context)

    nc = Nonconformity.create({
        "name": title,
        "description": nc_description,
    })

    return f"Nonconformity documented: {nc.name} (ID: {nc.id})"
